// Verify RelayOS webhook signature
// Requires credential: relayOsWebhookSecret (per-business secret)

const signature = $request.headers["x-relayos-signature"];
const timestamp = $request.headers["x-relayos-timestamp"];
const nonce = $request.headers["x-relayos-nonce"];
const rawBody = $request.rawBody;

// 1. Check required headers exist
if (!signature || !timestamp || !nonce) {
  throw new Error("Missing RelayOS signature headers (x-relayos-signature, x-relayos-timestamp, x-relayos-nonce)");
}

// 2. Check signature format
if (!signature.startsWith("v1=")) {
  throw new Error("Invalid signature format: must start with 'v1='");
}

// 3. Parse timestamp safely
const requestTime = parseInt(timestamp, 10);
if (isNaN(requestTime)) {
  throw new Error("Invalid timestamp: not a number");
}

// 4. Check timestamp drift (5 minutes = 300 seconds)
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - requestTime) > 300) {
  throw new Error("Timestamp out of acceptable range (replay protection: 5 minutes)");
}

// 5. Raw body must exist
if (rawBody === undefined || rawBody === null) {
  throw new Error("Missing raw request body for signature verification");
}

// 6. Reconstruct canonical string EXACTLY: timestamp.nonce.rawBody
const canonical = `${timestamp}.${nonce}.${rawBody}`;

// 7. Get per-business secret from n8n Credentials
const secret = $credentials.relayOsWebhookSecret;
if (!secret) {
  throw new Error("Per-business webhook secret not configured in credentials");
}

// 8. Compute expected signature
const crypto = require('crypto');
const expectedSignature = 'v1=' + crypto.createHmac('sha256', secret).update(canonical).digest('hex');

// 9. Timing-safe comparison
const sigBuffer = Buffer.from(signature, 'utf8');
const expectedBuffer = Buffer.from(expectedSignature, 'utf8');
if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
  throw new Error("Invalid signature");
}

// 10. Verification passed - pass through original payload unchanged
return [{ json: $json }];

